-- =====================================================================
-- V7_12 — TANKER_OUTBOUND workflow + 4 supporting persona pages.
--
-- Mirrors TankerInbound but for outbound (FG dispatch / loaded-tanker exit):
--   DRAFT → GATE_PASS_CREATED → DISPATCH_LOAD_ENTRY → LOADING_IN_PROGRESS
--         → WEIGHMENT_LOADED_OUT → QC_FINAL_OUT → GATE_PASS_OUT_CLOSED
--
-- Persona sequence:
--   FrontGate -> Dispatch -> UnloadingSupervisor (acts as loading supervisor)
--   -> WeighmentOfficer -> QC -> FrontGate
--
-- Pages added: pico:dispatch-load-entry, pico:loading-in-progress,
--              pico:qc-final-out, pico:gate-pass-out-closure
-- =====================================================================

-- 1. Replace skeleton TankerOutbound body --------------------------------
UPDATE workflow_definition
SET body_json = '{"code":"M10.TankerOutbound","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"Dispatch"},{"code":"DISPATCH_LOAD_ENTRY","assignedRole":"UnloadingSupervisor"},{"code":"LOADING_IN_PROGRESS","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_LOADED_OUT","assignedRole":"QC"},{"code":"QC_FINAL_OUT","assignedRole":"FrontGate"},{"code":"GATE_PASS_OUT_CLOSED","terminal":true},{"code":"QC_FINAL_OUT_REJECTED","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"pico:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"DISPATCH_LOAD_ENTRY","trigger":"page.submitted","pageCode":"pico:dispatch-load-entry"},{"from":"DISPATCH_LOAD_ENTRY","to":"LOADING_IN_PROGRESS","trigger":"page.submitted","pageCode":"pico:loading-in-progress"},{"from":"LOADING_IN_PROGRESS","to":"WEIGHMENT_LOADED_OUT","trigger":"page.submitted","pageCode":"pico:weighment-capture"},{"from":"WEIGHMENT_LOADED_OUT","to":"QC_FINAL_OUT","trigger":"page.submitted","pageCode":"pico:qc-final-out","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHMENT_LOADED_OUT","to":"QC_FINAL_OUT_REJECTED","trigger":"page.submitted","pageCode":"pico:qc-final-out","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_FINAL_OUT","to":"GATE_PASS_OUT_CLOSED","trigger":"page.submitted","pageCode":"pico:gate-pass-out-closure"}]}'
WHERE tenant_id=1 AND code='M10.TankerOutbound' AND version=1;

-- 2. Pages ----------------------------------------------------------------
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:dispatch-load-entry','Dispatch Load Entry','Dispatch officer captures load + customer + invoice for outbound tanker.','M10.Dispatch','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:dispatch-load-entry');
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:loading-in-progress','Loading Progress','Loading supervisor logs start / fill / finish.','M10.Dispatch','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:loading-in-progress');
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:qc-final-out','QC Final Outbound','Final QC sign-off before tanker exits.','M10.Dispatch','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:qc-final-out');
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:gate-pass-out-closure','Close Outbound Gate Pass','Front-gate exit-stamp for tanker out.','M10.Dispatch','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:gate-pass-out-closure');

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Load + Customer","fields":[{"kind":"FormField","type":"text","name":"customer","label":"Customer"},{"kind":"FormField","type":"text","name":"invoiceNo","label":"Invoice #"},{"kind":"FormField","type":"number","name":"plannedQty","label":"Planned Qty (kg)"},{"kind":"FormField","type":"text","name":"tankSource","label":"Source Tank"},{"kind":"WorkflowActionButton","label":"Assign Loading Supervisor","action":"workflow.transition","variant":"primary"}]}]}', 'V7_12', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:dispatch-load-entry' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Loading","fields":[{"kind":"FormField","type":"text","name":"loadingStart","label":"Started At","placeholder":"timestamp"},{"kind":"FormField","type":"text","name":"loadingEnd","label":"Finished At","placeholder":"timestamp"},{"kind":"FormField","type":"text","name":"sealNo","label":"Seal #"},{"kind":"WorkflowActionButton","label":"Capture Loaded Weight","action":"workflow.transition","variant":"primary"}]}]}', 'V7_12', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:loading-in-progress' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Final QC","fields":[{"kind":"FormField","type":"text","name":"sampleColour","label":"Sample Colour"},{"kind":"FormField","type":"text","name":"sampleOdour","label":"Sample Odour"},{"kind":"FormField","type":"text","name":"densityCheck","label":"Density (g/cc)"},{"kind":"FormField","type":"select","name":"status","label":"Outcome","options":[{"label":"APPROVED","value":"APPROVED"},{"label":"REJECTED","value":"REJECTED"}]},{"kind":"WorkflowActionButton","label":"Submit QC Outcome","action":"workflow.transition","variant":"primary"}]}]}', 'V7_12', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:qc-final-out' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Exit Verification","fields":[{"kind":"FormField","type":"text","name":"gpNumber","label":"Gate Pass #"},{"kind":"FormField","type":"text","name":"exitNotes","label":"Notes"},{"kind":"WorkflowActionButton","label":"Exit-Stamp","action":"workflow.transition","variant":"primary"}]}]}', 'V7_12', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:gate-pass-out-closure' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code IN ('pico:dispatch-load-entry','pico:loading-in-progress','pico:qc-final-out','pico:gate-pass-out-closure') AND current_version_id IS NULL;
